<?php

# @autogenerated
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRelyingPartyVO;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\RelyingPartyRef;

final class PlatformIdentityRelyingPartyVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = new RelyingPartyRef('one');
        $ref = PlatformIdentityRelyingPartyVO::from($value);
        $this->assertEquals(new RelyingPartyRef('one'), $ref->value());
        $other = PlatformIdentityRelyingPartyVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = PlatformIdentityRelyingPartyVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = PlatformIdentityRelyingPartyVO::tryFrom('1', $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_optimist_asignation_invalid_type(): void
    {
        $this->expectException(ConstraintException::class);
        $method = new ReflectionMethod(PlatformIdentityRelyingPartyVO::class, 'fromUnsafe');
        $method->invoke(null, [11, "bad"]);
    }
    public function test_equals(): void
    {
        $one = PlatformIdentityRelyingPartyVO::from(new RelyingPartyRef('one'));
        $same = PlatformIdentityRelyingPartyVO::from(new RelyingPartyRef('one'));
        $other = PlatformIdentityRelyingPartyVO::from(new RelyingPartyRef('other'));
        $withEmpty = $one->equals(null);
        $withSame = $one->equals($same);
        $withOther = $one->equals($other);

        $this->assertFalse($withEmpty);
        $this->assertTrue($withSame);
        $this->assertFalse($withOther);
    }
    public function test_empty(): void
    {
        $ref = PlatformIdentityRelyingPartyVO::empty();
        $this->assertNull($ref->value());
    }
    public function test_try_from_empty(): void
    {
        $ref = PlatformIdentityRelyingPartyVO::tryFrom(null, new ConstraintFailList());
        $this->assertNull($ref->value());
    }
}
